/* ---------- JS Studio ---------- */
function studio(){const parts={memory:studioMemory,brief:studioBrief,taslak:studioDraft,surumler:studioVersions};return head('ÜRETİM & MEDYA · JS STUDIO','Bir fikrin bütün halleri.','Brand Memory, 5 unsurlu brief, Copy rol ikizinin ilk taslağı ve ECD ön-kontrolü. Ortak bir yaratıcı hafıza.',btn('Yeni brief','studio-brief-new','primary','plus'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||studioMemory)()}`}
function studioMemory(){const id=ui.bm||'c_wellana';const bm=state.brandMemory.find(b=>b.client===id);const i=state.brandMemory.indexOf(bm);return `<div class="toolbar"><label class="form-field" style="min-width:240px">Marka<select data-ui-sel="bm">${state.brandMemory.map(b=>option(b.client,client(b.client),id)).join('')}</select></label>${badge(`Güncelleme ${bm?.updated}`,'neutral')}</div>${bm?`<div class="profile-grid"><section class="panel"><h2>Ton rehberi</h2><p class="hint">İkizler ve AI taslakları bu tonu kullanır.</p><textarea data-bind="brandMemory.${i}.tone" maxlength="400">${esc(bm.tone)}</textarea></section><section class="panel"><h2>Yasaklı ifadeler</h2><p class="hint">ECD ön-kontrolü bu listeyi tarar.</p>${chips(`brandMemory.${i}.banned`,bm.banned,'İfade ekle')}</section><section class="panel"><h2>Görsel kurallar</h2><textarea data-bind="brandMemory.${i}.visual" maxlength="400">${esc(bm.visual)}</textarea></section><section class="panel"><h2>Geçmiş işler</h2><ul class="meeting-list">${bm.past.map(p=>`<li>${ic('files')}<span>${esc(p)}</span></li>`).join('')}</ul><div class="form-actions" style="justify-content:start">${btn('Medya kütüphanesinde aç','goto','sm','media','data-id="media/kutuphane"')}</div></section></div>`:'<p class="empty">Bu marka için hafıza yok.</p>'}`}
function studioBrief(){return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Brief formu · 5 zorunlu unsur</h2></div><div class="panel-body"><form id="brief-form" class="form-grid"><label class="form-field">Marka<select name="client">${state.clients.map(c=>option(c.id,c.name,'c_wellana')).join('')}</select></label><label class="form-field">Başlık<input name="title" required maxlength="90"></label><label class="form-field full">01 · Neyi değiştirmek istiyoruz?<textarea name="goal" required maxlength="300"></textarea></label><label class="form-field full">02 · Kimin için?<textarea name="audience" required maxlength="300"></textarea></label><label class="form-field full">03 · Beklenen çıktılar<textarea name="outputs" required maxlength="300"></textarea></label><label class="form-field full">04 · Başarıyı nasıl okuyacağız?<textarea name="success" required maxlength="300"></textarea></label><label class="form-field full">05 · Sınırlar & teslim<textarea name="limits" required maxlength="300"></textarea></label><div class="form-actions" style="grid-column:1/-1;justify-content:start"><button class="button primary" type="submit">Briefi kaydet ${ic('check')}</button>${btn('AI konsept üret','studio-generate','','spark')}</div></form></div></div><div class="panel"><div class="panel-header"><h2>Briefler</h2></div><div class="panel-body">${state.briefs.map(b=>`<div class="session-row"><div><strong>${esc(b.title)}</strong><small>${esc(client(b.client))} · ${esc(b.at)}</small></div>${badge(b.status)}</div>`).join('')}</div></div></section>`}
function studioDraft(){const c=state.concepts[0];const bm=state.brandMemory.find(b=>b.client===c.client);const checks=[['tone','Ton rehberine uygun'],['banned','Yasaklı ifade yok'],['visual','Görsel kuralla uyumlu'],['claim','Sağlık/performans iddiası yok'],['length','Uzunluk kanal limitinde']];const ok=checks.filter(([k])=>c.ecd[k]).length;return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>${esc(c.title)}</h2><div class="actions">${badge('Copy rol ikizi','ai')}${badge(c.version,'neutral')}${badge(c.status)}</div></div><div class="panel-body"><p class="small muted">Brief: ${esc(state.briefs.find(b=>b.id===c.brief)?.title)} · ${esc(client(c.client))} · AI çıktısı taslaktır; yayın öncesi ECD ve müşteri onayı şart.</p><textarea id="concept-text" data-bind="concepts.0.text" style="min-height:220px">${esc(c.text)}</textarea><div class="form-actions" style="justify-content:start">${btn('Yeni sürüm kaydet','concept-version','primary','plus')}${btn('Alternatif üret','studio-generate','','spark')}${btn('JS Social’a aktar','concept-to-social','','social')}</div></div></div><div class="panel"><div class="panel-header"><h2>ECD ön-kontrol listesi</h2>${badge(`${ok}/${checks.length}`,ok===checks.length?'success':'warn')}</div><div class="panel-body">${checks.map(([k,l])=>`<div class="toggle-row"><div>${l}<small>${k==='banned'?`Liste: ${bm?.banned.join(', ')}`:k==='claim'?'KVKK/reklam kurulu riski':'Brand Memory'}</small></div>${sw(`concepts.0.ecd.${k}`,c.ecd[k],l,'data-rerender')}</div>`).join('')}<div class="form-actions" style="justify-content:start">${btn(ok===checks.length?'ECD onayı ver':'Eksikler var','concept-approve',ok===checks.length?'primary':'','check',ok===checks.length?'':'disabled')}</div></div></div></section>`}
function studioVersions(){return tbl(['SÜRÜM','KONSEPT','ZAMAN','NOT',''],state.concepts.flatMap(c=>c.versions.map(v=>`<tr><td><strong>${v.v}</strong>${v.v===c.version?' '+badge('güncel','success'):''}</td><td>${esc(c.title)}</td><td>${esc(v.at)}</td><td>${esc(v.note)}</td><td>${v.v!==c.version?btn('Geri al','concept-restore','sm','refresh',`data-id="${c.id}" data-v="${v.v}"`):''}</td></tr>`)).join(''),'Sürümler')}

/* ---------- JS Social ---------- */
const socialStages=['Fikir','Metin','Görsel','İç onay','Müşteri onayı','Yayın'];
function social(){const parts={takvim:socialCalendar,kartlar:socialCards,kota:socialQuota};return head('ÜRETİM & MEDYA · JS SOCIAL','Takvim, onay, yayın.','Marka × ay içerik takvimi. Pipeline: fikir → metin → görsel → iç onay → müşteri onayı → yayın. Kota sözleşmeden okunur.',btn('Aylık plan üret (SM ikizi)','social-plan','primary','spark')+btn('İçerik ekle','social-new','','plus'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||socialCalendar)()}`}
function socialCalendar(){const id=ui.socialBrand||'c_badem';const items=state.social.filter(s=>s.client===id&&s.month==='2026-10');const first=new Date('2026-10-01T12:00:00').getDay();const offset=(first+6)%7;const cells=[...Array(offset)].map(()=>'<div class="cal-cell empty"></div>').concat([...Array(31)].map((_,i)=>{const d=i+1;const its=items.filter(x=>x.day===d);return `<div class="cal-cell ${d===14?'today':''}"><span class="cal-day">${d}</span>${its.map(x=>`<button class="cal-item st-${socialStages.indexOf(x.stage)}" data-action="social-open" data-id="${x.id}" title="${esc(x.text)} · ${esc(x.stage)}">${x.channel==='Reels'?'▶ ':''}${esc(x.text)}</button>`).join('')}</div>`}));return `<div class="toolbar"><label class="form-field" style="min-width:220px">Marka<select data-ui-sel="socialBrand">${state.clients.filter(c=>state.social.some(s=>s.client===c.id)||state.contracts.some(x=>x.client===c.id)).map(c=>option(c.id,c.name,id)).join('')}</select></label><span class="muted small">Ekim 2026 · ${items.length} içerik</span>${btn('Toplu müşteri onayına gönder','social-bulk','sm','portal',`data-id="${id}"`)}</div><div class="cal-head">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar">${cells.join('')}</div><div class="legend">${socialStages.map((s,i)=>`<span><i class="st-${i}"></i>${s}</span>`).join('')}</div>`}
function socialCards(){const id=ui.socialBrand||'c_badem';return `<div class="toolbar"><label class="form-field" style="min-width:220px">Marka<select data-ui-sel="socialBrand">${state.clients.filter(c=>state.social.some(s=>s.client===c.id)).map(c=>option(c.id,c.name,id)).join('')}</select></label></div>${kanban(socialStages,state.social.filter(s=>s.client===id),s=>`<button class="kcard-title" data-action="social-open" data-id="${s.id}">${esc(s.text)}</button><small>${esc(s.channel)} · ${s.day} Eki · ${esc(s.visual)}</small>`,'social-move',s=>s.stage)}`}
function socialQuota(){return `<div class="project-grid">${state.contracts.map(ct=>{const n=state.social.filter(s=>s.client===ct.client&&s.month==='2026-10');const posts=n.filter(s=>s.channel!=='Reels').length,reels=n.filter(s=>s.channel==='Reels').length;return `<article class="panel contract-card"><div class="card-top"><h2>${esc(client(ct.client))}</h2>${badge(posts>ct.quota.social||reels>ct.quota.reels?'Kota aşımı':'Kota içinde',posts>ct.quota.social||reels>ct.quota.reels?'danger':'success')}</div><div class="quota-row"><span>Planlanan post</span>${meter(posts/ct.quota.social*100,posts>ct.quota.social?'danger':'')}<small>${posts} / ${ct.quota.social}</small></div><div class="quota-row"><span>Planlanan Reels</span>${meter(reels/Math.max(1,ct.quota.reels)*100,reels>ct.quota.reels?'danger':'')}<small>${reels} / ${ct.quota.reels}</small></div><div class="quota-row"><span>Revize turu</span>${meter(ct.used.revize/Math.max(1,ct.quota.revize)*100)}<small>${ct.used.revize} / ${ct.quota.revize}</small></div><p class="small muted" style="margin-top:8px">Yayınlanan: ${n.filter(s=>s.stage==='Yayın').length} · müşteri onayında: ${n.filter(s=>s.stage==='Müşteri onayı').length}</p></article>`}).join('')}</div>`}
function socialDetail(id){const s=state.social.find(x=>x.id===id);if(!s)return;const i=state.social.indexOf(s);openDialog(`${esc(client(s.client))} · ${s.day} Ekim`,`<div class="dialog-body"><div class="pipeline">${socialStages.map((st,k)=>`<span class="${socialStages.indexOf(s.stage)>=k?'done':''}">${st}</span>`).join('')}</div><div class="form-grid" style="margin-top:14px"><label class="form-field">Kanal${sel(`social.${i}.channel`,['Instagram','Reels','LinkedIn','Facebook','TikTok'],s.channel)}</label><label class="form-field">Aşama${sel(`social.${i}.stage`,socialStages,s.stage,'data-rerender')}</label><label class="form-field full">Metin<textarea data-bind="social.${i}.text" maxlength="400">${esc(s.text)}</textarea></label><label class="form-field">Görsel<input data-bind="social.${i}.visual" value="${esc(s.visual)}"></label><label class="form-field">Gün<input type="number" min="1" max="31" data-bind="social.${i}.day" data-number value="${s.day}"></label></div><div class="form-actions">${btn('Sil','social-delete','danger','trash',`data-id="${s.id}"`)}${btn('Kapat','close','primary','check')}</div></div>`)}

/* ---------- JS Media ---------- */
function media(){const parts={kutuphane:mediaLibrary,vimeo:mediaVimeo,saklama:mediaRetention};return head('ÜRETİM & MEDYA · JS MEDIA','Her şey, yerli yerinde.','Vimeo Advanced metadata (2.000+ video), MinIO/S3 dosyaları ve Drive bağlantıları tek kütüphanede. Müşteriye kalıcı URL verilmez; kısa ömürlü imzalı link üretilir.',isClient()?'':btn('Dosya yükle','goto','primary','upload','data-id="transfer/yukle"'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||mediaLibrary)()}`}
function mediaLibrary(){const b=ui.mBrand||'',p=ui.mProject||'',t=ui.mType||'';const list=state.assets.filter(a=>inScope(a.client)&&(!isClient()||['Onaylı','Arşiv','Müşteri onayı','İncelemede'].includes(a.status))&&(!b||a.client===b)&&(!p||a.project===p)&&(!t||a.type===t));return `<div class="toolbar filters"><label class="form-field">Marka<select data-ui-sel="mBrand"><option value="">Tümü</option>${state.clients.filter(c=>inScope(c.id)).map(c=>option(c.id,c.name,b)).join('')}</select></label><label class="form-field">Proje<select data-ui-sel="mProject"><option value="">Tümü</option>${myProjects().map(x=>option(x.id,x.name,p)).join('')}</select></label><label class="form-field">Tür<select data-ui-sel="mType"><option value="">Tümü</option>${['Video','Görsel','PDF','Sunum'].map(x=>option(x,x,t)).join('')}</select></label><span class="muted small">${list.length} kayıt</span></div>${tbl(['DOSYA','TÜR','KAYNAK','MARKA / PROJE','BOYUT','SAKLAMA','DURUM',''],list.map(a=>`<tr><td><div class="name-cell">${ic(a.type==='Video'?'media':'files')}<div>${esc(a.name)}<small>${esc(a.folder)}${a.vimeoId?` · vimeo:${a.vimeoId}`:''}${a.key?` · <span class="mono">${esc(a.key)}</span>`:''}</small></div></div></td><td>${esc(a.type)}${a.duration?`<small>${a.duration}</small>`:''}</td><td>${badge(a.provider,'neutral')}</td><td>${esc(client(a.client))}<small>${esc(project(a.project)?.name||'—')}</small></td><td>${esc(a.size)}</td><td>${date(a.retention)}</td><td>${badge(a.status)}</td><td><div class="actions"><button class="button sm" data-action="file-preview" data-id="${a.id}">Önizle</button>${a.type==='Video'?btn('İncele','review-open','sm','review',`data-id="${a.id}"`):''}${isClient()?'':btn('Link','file-share','sm','link',`data-id="${a.id}"`)}</div></td></tr>`).join(''),'Medya kütüphanesi')}`}
function mediaVimeo(){const v=state.vimeoImport;const pct=Math.round(v.imported/v.total*100);return `<section class="metrics">${metric('Vimeo videoları',v.total.toLocaleString('tr-TR'),'Advanced hesap · metadata referansı','media')}${metric('İçe aktarılan',v.imported.toLocaleString('tr-TR'),`%${pct} · son çalışma ${v.lastRun}`,'check')}${metric('Bekleyen',v.pending,`${v.errors} hata (yeniden dene)`,'clock')}${metric('Arşiv',`${v.archiveTB} <small>/ ${v.quotaTB} TB</small>`,'Başka sağlayıcıda aynı kota garanti değildir','files')}</section><section class="panel"><div class="panel-header"><h2>İçe aktarım durumu</h2>${badge(v.pending?'Devam ediyor':'Tamamlandı')}</div><div class="panel-body">${meter(pct)}<p class="small muted" style="margin:10px 0">Vimeo video ID + metadata JS Media’ya referans olarak alınır; dosya taşınmaz. Seçili dosyada göç pilotu sonraki fazdır.</p><div class="form-actions" style="justify-content:start">${btn('Bekleyenleri işle','vimeo-run','primary','play')}${btn('Hataları yeniden dene','vimeo-retry','','refresh')}</div></div></section>`}
function mediaRetention(){return `<div class="banner">${ic('shield')}<span>Erişim: JS linki yetki kontrolünden sonra kısa ömürlü (15 dk) ön-imzalı URL üretir. Müşteri kalıcı object-storage adresi görmez; her indirme audit’e yazılır.</span></div>${tbl(['SINIF','SAKLAMA','SONRA','KAYIT'],[['Müşteri teslimleri (onaylı)','5 yıl','Soğuk arşiv (S3 Glacier)',state.assets.filter(a=>a.status==='Onaylı').length],['Çalışma dosyaları (PSD/AI/PRPROJ)','3 yıl','Sil (müşteri bildirimli)',state.assets.filter(a=>['İç revize','Onay','Taslak'].includes(a.status)).length],['Ham çekim','18 ay','Sil',2],['İnceleme sürümleri','1 yıl','Yalnızca final kalır',state.reviews.reduce((s,r)=>s+r.versions.length,0)]].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''),'Saklama politikası')}<section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Süresi yaklaşan</h2></div><div class="panel-body">${state.assets.filter(a=>daysFromToday(a.retention)<400).map(a=>`<div class="session-row"><div>${esc(a.name)}<small>${date(a.retention)} · ${daysFromToday(a.retention)} gün</small></div>${btn('Süreyi uzat','retention-extend','sm','clock',`data-id="${a.id}"`)}</div>`).join('')||'<p class="empty">Önümüzdeki 400 günde süresi dolan dosya yok.</p>'}</div></section>`}

/* ---------- JS Review ---------- */
function review(){const parts={inceleme:reviewPage,dis:reviewExternal};return head('ÜRETİM & MEDYA · JS REVIEW','Doğru kare, doğru not.','Zaman kodlu yorum, müşteri-görünür / dahili ayrımı, sürüm karşılaştırma ve revize turu sayacı. Onay audit’e yazılır.',isClient()?'':btn('Yeni sürüm yükle','review-version','primary','upload'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||reviewPage)()}`}
function reviewPage(){const list=state.reviews.filter(r=>inScope(r.client));const r=list.find(x=>x.id===ui.review)||list[0];if(!r)return '<p class="empty">İnceleme yok.</p>';const ver=r.versions.find(v=>v.v===(ui.rv||r.current))||r.versions.at(-1);const comments=ver.comments.filter(c=>!isClient()||!c.internal).filter(c=>ui.rvFilter==='open'?!c.resolved:true);return `<div class="toolbar"><label class="form-field" style="min-width:240px">İş<select data-ui-sel="review">${list.map(x=>option(x.id,x.name,r.id)).join('')}</select></label><label class="form-field">Sürüm<select data-ui-sel="rv">${r.versions.map(v=>option(v.v,`${v.v} · ${v.at}`,ver.v)).join('')}</select></label>${badge(r.status)}${badge(`Revize turu ${r.rounds.used} / ${r.rounds.included} dahil`,r.rounds.used>=r.rounds.included?'warn':'neutral')}</div><section class="content-grid"><div class="panel"><div class="video-stage"><div class="video-frame"><span class="vf-title">${esc(r.name)} <small>${ver.v}</small></span>${ic('play')}<span class="vf-tc">00:${ui.tc||'00'} / ${ver.duration}</span><div class="vf-track">${ver.comments.map(c=>`<i style="left:${tcPct(c.tc,ver.duration)}%" class="${c.resolved?'res':''}" title="${c.tc}"></i>`).join('')}</div></div></div><div class="panel-body" style="padding-top:16px"><form id="review-comment-form" data-id="${r.id}" data-v="${ver.v}" class="form-grid"><label class="form-field">Zaman kodu<input name="tc" pattern="\\d\\d:\\d\\d" value="00:${ui.tc||'30'}" required></label><label class="form-field">Görünürlük<select name="vis">${isClient()?'<option value="client">Müşteri yorumu</option>':'<option value="internal">Dahili</option><option value="client">Müşteriye görünür</option>'}</select></label><label class="form-field full">Yorum<textarea name="text" required maxlength="300" placeholder="Örn. 00:45 — geçiş hızını azaltalım"></textarea></label><div class="form-actions" style="grid-column:1/-1;justify-content:start"><button class="button primary" type="submit">Yorum ekle ${ic('plus')}</button></div></form></div></div><div class="panel"><div class="panel-header"><h2>Yorumlar <span class="muted small">${comments.length}</span></h2><div class="actions"><button class="tab ${ui.rvFilter!=='open'?'active':''}" data-action="rv-filter" data-id="all">Tümü</button><button class="tab ${ui.rvFilter==='open'?'active':''}" data-action="rv-filter" data-id="open">Açık</button></div></div><div class="panel-body">${comments.map(c=>`<div class="comment ${c.internal?'internal':''} ${c.resolved?'resolved':''}"><small><code class="mono">${c.tc}</code> · ${esc(c.who)} ${c.internal?badge('Dahili'):badge('Müşteri görür','success')}${c.resolved?' '+badge('Çözüldü'):''}</small><p>${esc(c.text)}</p>${isClient()&&c.resolved?'':`<div class="actions">${c.resolved?'':btn('Çözüldü','rv-resolve','sm','check',`data-id="${r.id}" data-v="${ver.v}" data-c="${c.id}"`)}${isClient()?'':btn(c.internal?'Müşteriye aç':'Dahili yap','rv-vis','sm','eye',`data-id="${r.id}" data-v="${ver.v}" data-c="${c.id}"`)}</div>`}</div>`).join('')||'<p class="empty">Bu görünümde yorum yok.</p>'}</div></div></section><div class="form-actions" style="justify-content:start;margin-top:16px">${r.status==='Onaylandı'?badge('Onaylandı'):btn('Onayla','rv-approve','primary','check',`data-id="${r.id}"`)+btn('Revizyon iste','rv-revise','','refresh',`data-id="${r.id}"`)}${isClient()?'':btn('JS Transfer linki oluştur','file-share','','transfer',`data-id="${r.asset}"`)}</div>`}
const tcPct=(tc,dur)=>{const s=t=>{const [m,ss]=t.split(':').map(Number);return m*60+ss};return Math.min(98,Math.round(s(tc)/Math.max(1,s(dur))*100))};
function reviewExternal(){return `<div class="banner">${ic('shield')}<span>Dış inceleyici linki: tek iş, süre sınırlı, yalnızca müşteri-görünür yorumlar. İndirme yetkisi ayrı verilir. Link iptal edilince erişim anında kapanır.</span></div>${tbl(['İŞ','LİNK','SON KULLANIM','İNDİRME','DURUM',''],state.reviews.filter(r=>inScope(r.client)).map(r=>`<tr><td>${esc(r.name)}<small>${esc(client(r.client))} · ${r.current}</small></td><td class="mono">${r.externalLink?esc(r.externalLink):'—'}</td><td>${r.externalLink?'7 gün':'—'}</td><td>${r.externalLink?badge('Kapalı','neutral'):'—'}</td><td>${r.externalLink?badge('Aktif'):badge('Link yok','neutral')}</td><td><div class="actions">${r.externalLink?btn('Kopyala','copy','sm','copy',`data-id="${r.externalLink}"`)+btn('İptal','rv-link-revoke','sm danger','close',`data-id="${r.id}"`):btn('Link oluştur','rv-link','sm','link',`data-id="${r.id}"`)}</div></td></tr>`).join(''),'Dış inceleyici linkleri')}`}

/* ---------- JS Transfer ---------- */
function transfer(){const parts={yukle:transferUpload,linkler:transferLinks,log:transferLog,istek:transferRequest};return head('ÜRETİM & MEDYA · JS TRANSFER','Büyük dosya, güvenli yol.','Parçalı yükleme → checksum/virüs taraması → asset kaydı. Süre, şifre ve indirme limitli paylaşım linkleri; her indirme loglanır.',btn('Yeni paylaşım linki','share-new','primary','link'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||transferUpload)()}`}
function transferUpload(){const up=ui.upload;return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Yükle</h2>${badge('Parçalı · S3 multipart','neutral')}</div><div class="panel-body"><div class="dropzone">${ic('upload')}<p>Sürükle-bırak ya da dosya seç · en fazla 5 GB · MP4, MOV, PDF, AI, PSD, ZIP</p><div class="form-grid"><label class="form-field">Dosya adı<input id="up-name" value="Anova_lansman_final_v3.mp4"></label><label class="form-field">Hedef<select id="up-to"><option>MinIO · jobs-media/anova</option><option>MinIO · jobs-media/badem</option><option>MinIO · jobs-media/wellana</option></select></label></div><div class="form-actions" style="justify-content:start">${btn(up?'Yükleniyor…':'Yüklemeyi başlat','upload-start','primary','upload',up?'disabled':'')}</div></div>${up?`<div class="upload-progress"><div class="session-row"><div><strong>${esc(up.name)}</strong><small id="up-stage">${esc(up.stage)}</small></div><strong id="up-pct">%${up.pct}</strong></div><div class="progress"><span id="up-bar" style="width:${up.pct}%"></span></div></div>`:''}</div></div><div class="panel"><div class="panel-header"><h2>Son yüklemeler</h2></div><div class="panel-body">${state.uploads.map(u=>`<div class="session-row"><div><strong>${esc(u.name)}</strong><small>${esc(u.size)} · ${esc(u.to)} · ${esc(u.at)} · <span class="mono">${esc(u.checksum)}</span></small></div>${badge(u.status)}</div>`).join('')}</div></div></section>`}
function transferLinks(){return tbl(['DOSYA','LİNK','SON TARİH','ŞİFRE','İNDİRME','DURUM',''],state.shareLinks.map(l=>{const expired=daysFromToday(l.expires)<0;const st=l.revoked?'İptal edildi':expired?'Süresi doldu':l.downloads>=l.limit?'Limit doldu':'Aktif';return `<tr><td>${esc(l.file)}<small>${esc(l.created)} · ${esc(person(l.by))}</small></td><td class="mono">${esc(l.url)}</td><td>${date(l.expires)}</td><td>${l.password?badge('Şifreli','success'):badge('Şifresiz','neutral')}</td><td>${l.downloads} / ${l.limit}</td><td>${badge(st,st==='Aktif'?'success':st==='Limit doldu'?'warn':'danger')}</td><td><div class="actions">${btn('Kopyala','copy','sm','copy',`data-id="${l.url}"`)}${st==='Aktif'?btn('İptal et','share-revoke','sm danger','close',`data-id="${l.id}"`):''}${expired&&!l.revoked?btn('Uzat','share-extend','sm','clock',`data-id="${l.id}"`):''}</div></td></tr>`}).join(''),'Paylaşım linkleri')}
function transferLog(){return tbl(['ZAMAN','LİNK / DOSYA','KİM','IP','SONUÇ'],state.downloadLog.map(d=>`<tr><td>${esc(d.at)}</td><td>${esc(state.shareLinks.find(l=>l.id===d.link)?.file||d.link)}</td><td class="mono">${esc(d.who)}</td><td class="mono">${esc(d.ip)}</td><td>${d.ok?badge('İndirildi','success'):badge('Reddedildi (şifre)','danger')}</td></tr>`).join(''),'İndirme logu')}
function transferRequest(){return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Dış kişiden dosya iste</h2></div><div class="panel-body"><form id="file-request-form" class="form-grid"><label class="form-field">E-posta<input type="email" name="to" required placeholder="kisi@marka.example"></label><label class="form-field">Son tarih<input type="date" name="expires" value="2026-10-24"></label><label class="form-field full">Ne istiyorsun?<input name="what" required maxlength="120" placeholder="Logo vektörleri, ürün fotoğrafları…"></label><div class="form-actions" style="grid-column:1/-1;justify-content:start"><button class="button primary" type="submit">İstek linki oluştur ${ic('link')}</button></div></form></div></div><div class="panel"><div class="panel-header"><h2>Açık istekler</h2></div><div class="panel-body">${state.fileRequests.map(f=>`<div class="session-row"><div><strong>${esc(f.what)}</strong><small>${esc(f.to)} · ${date(f.expires)} · <span class="mono">${esc(f.url)}</span></small></div>${f.received?badge(`${f.received} dosya geldi`,'success'):badge('Bekliyor')}</div>`).join('')}</div></div></section>`}

/* ---------- JS Present ---------- */
function present(){const parts={teklif:presentQuote,sunum:()=>presentDocs('Sunum'),rapor:()=>presentDocs('Rapor'),sablon:presentTemplates};return head('ÜRETİM & MEDYA · JS PRESENT','Anlat, ikna et, raporla.','CRM kalemlerinden teklif belgesi; ikiz saat tahmini ve marj kontrolü; sunum ve aylık müşteri raporu taslakları; şablon kütüphanesi.',btn('Yeni belge','doc-new','primary','plus'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||presentQuote)()}`}
function presentQuote(){const q=state.quotes.find(x=>x.id===(ui.quote||'Q-2026-041'))||state.quotes[0];const total=q.items.reduce((s,[,n,p])=>s+n*p,0);const cost=q.hours*RATE;const margin=Math.round((total-cost)/total*100);return `<div class="toolbar"><label class="form-field" style="min-width:260px">Teklif<select data-ui-sel="quote">${state.quotes.map(x=>option(x.id,`${x.id} · ${x.name}`,q.id)).join('')}</select></label>${badge(q.status)}</div><section class="content-grid"><div class="panel doc-preview"><div class="doc-page"><div class="eyebrow">JOBS STUDIO · TEKLİF</div><h2>${esc(q.name)}</h2><p class="small muted">${q.client?esc(client(q.client)):'Yeni şirket'} · Geçerlilik ${date(q.valid)} · ${q.id}</p><table class="vel-table"><thead><tr><th>KALEM</th><th>ADET</th><th>TUTAR</th></tr></thead><tbody>${q.items.map(([d,n,p])=>`<tr><td>${esc(d)}</td><td>${n}</td><td>${money(n*p)}</td></tr>`).join('')}<tr><td><strong>Toplam (KDV hariç)</strong></td><td></td><td><strong>${money(total)}</strong></td></tr></tbody></table><p class="small muted" style="margin-top:14px">Ödeme: %50 başlangıç, %50 teslim · Revize: 2 tur dahil · Kullanım hakları teklif ekinde.</p></div></div><div><div class="panel" style="margin-bottom:16px"><div class="panel-header"><h2>İkiz saat tahmini</h2>${badge('Traffic rol ikizi','ai')}</div><div class="panel-body"><p><strong>${q.hours} saat</strong> · ${money(cost)} iç maliyet (${money(RATE)}/s)</p><p class="small muted">Kalemler ikizlerin görev türü hızlarından toplanır; sapma ±%12.</p></div></div><div class="panel" style="margin-bottom:16px"><div class="panel-header"><h2>Marj kontrolü</h2>${badge(`%${margin}`,margin<35?'danger':margin<45?'warn':'success')}</div><div class="panel-body">${meter(margin,margin<35?'danger':'')}<p class="small muted" style="margin-top:8px">Hedef ≥ %45 · %35 altı CFO ajanı uyarısı üretir ve Onay Merkezi’ne düşer.</p></div></div><div class="form-actions" style="justify-content:start">${btn('PDF taslağı üret','present-pdf','primary','download',`data-id="${q.id}"`)}${btn('Müşteriye gönder','quote-send','','mail',`data-id="${q.id}"`)}</div></div></section>`}
function presentDocs(kind){const docs=state.documents.filter(d=>d.type===kind);return `<div class="project-grid">${docs.map(d=>`<article class="panel brief-card"><div class="cover ${kind==='Rapor'?'alt':''}"><div class="orbit" aria-hidden="true"></div><span style="z-index:1">${esc(d.name.split(' · ')[0])}</span></div>${badge(d.status)}<h2>${esc(d.name)}</h2><p>${esc(client(d.client))} · ${d.pages} sayfa · güncelleme ${esc(d.updated)}</p><div class="actions">${btn('Taslağı üret','doc-generate','sm','spark',`data-id="${d.id}"`)}${d.status==='Taslak'?btn('Gönder','doc-send','sm','mail',`data-id="${d.id}"`):btn('PDF','present-pdf','sm','download',`data-id="${d.id}"`)}</div></article>`).join('')}<article class="panel brief-card new"><h2>${kind==='Sunum'?'Yeni sunum taslağı':'Yeni aylık rapor'}</h2><p>${kind==='Sunum'?'Brand Memory + brief → 12–24 slayt yapı önerisi.':'JS Social, JS Review ve JS Finance verisinden aylık müşteri raporu.'}</p>${btn('Oluştur','doc-new','primary','plus',`data-kind="${kind}"`)}</article></div>`}
function presentTemplates(){return tbl(['ŞABLON','TÜR','KULLANIM',''],state.docTemplates.map(t=>`<tr><td>${esc(t.name)}</td><td>${badge(t.kind,'neutral')}</td><td>${t.uses}</td><td>${btn('Bu şablonla başla','doc-new','sm','plus',`data-kind="${t.kind}"`)}</td></tr>`).join(''),'Şablon kütüphanesi')}

/* ---------- JS Marketing ---------- */
function marketing(){const parts={kitle:mkSegments,kampanya:mkCampaigns,diziler:mkSequences,bulten:mkNewsletter,form:mkForms,huni:mkFunnel};return head('ÜRETİM & MEDYA · JS MARKETING','Ajansın kendi pazarlaması.','Segmentler (KVKK izin durumu), mailing, otomatik diziler, bülten, lead formu/UTM ve huni raporu: kampanya → lead → teklif → kazanım, CAC.',btn('Yeni kampanya','campaign-new','primary','plus'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||mkSegments)()}`}
function mkSegments(){return tbl(['SEGMENT','KİŞİ','KVKK İZİNLİ','İZİN ORANI',''],state.segments.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.count}</td><td>${s.kvkk}</td><td><div class="health-bar">${meter(s.kvkk/s.count*100)}<small>%${Math.round(s.kvkk/s.count*100)}</small></div></td><td>${btn('Kampanya aç','campaign-new','sm','mail',`data-id="${s.id}"`)}</td></tr>`).join(''),'Segmentler','Yalnızca KVKK açık rızası olan kişilere gönderim yapılır; diğerleri listeden otomatik düşer.')}
function mkCampaigns(){return tbl(['KAMPANYA','SEGMENT','A/B KONU','GÖNDERİM','AÇILMA','TIKLAMA','DURUM',''],state.campaigns.map(c=>`<tr><td>${esc(c.name)}<small>${esc(c.at)}</small></td><td>${esc(state.segments.find(s=>s.id===c.segment)?.name)}</td><td><small>A: ${esc(c.subjectA)}</small><br><small>B: ${esc(c.subjectB||'—')}</small>${c.winner?' '+badge(`Kazanan ${c.winner}`,'success'):''}</td><td>${c.sent}</td><td>${c.sent?Math.round(c.open/c.sent*100)+'%':'—'}</td><td>${c.sent?Math.round(c.click/c.sent*100)+'%':'—'}</td><td>${badge(c.status)}</td><td><div class="actions">${c.status==='Taslak'?btn('Test gönder','campaign-test','sm','mail',`data-id="${c.id}"`)+btn('Zamanla','campaign-schedule','sm','clock',`data-id="${c.id}"`):''}${c.status==='Zamanlandı'?btn('Şimdi gönder','campaign-send','sm','play',`data-id="${c.id}"`):''}</div></td></tr>`).join(''),'Kampanyalar')}
function mkSequences(){return `<div class="project-grid">${state.sequences.map(s=>`<article class="panel contract-card"><div class="card-top"><div><h2>${esc(s.name)}</h2><small class="muted">Tetik: <code class="mono">${esc(s.trigger)}</code> · ${s.enrolled} kişi akışta</small></div>${sw(`sequences.${state.sequences.indexOf(s)}.active`,s.active,`${s.name} aktif`,'data-rerender')}</div><ol class="steps">${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></article>`).join('')}</div>`}
function mkNewsletter(){const c=state.campaigns[0];return `<section class="content-grid"><div class="panel doc-preview"><div class="doc-page"><div class="eyebrow">JOBS STUDIO · BÜLTEN · EKİM 2026</div><h2>Ajans notları</h2><p>Bu ay: 3 lansman, 1 etkinlik ve JS Review ile 1 güne inen video onayı.</p><ul><li>Anova lansman filmi: storyboard’dan kurguya 9 gün.</li><li>Badem Pınarı “kaynağından”: 8 post, 2 Reels, %4,8 etkileşim.</li><li>Numesys yıl sonu: 320 kişi, LCV açık.</li></ul><p class="small muted">Abonelikten çıkma bağlantısı ve KVKK metni otomatik eklenir.</p></div></div><div class="panel"><div class="panel-header"><h2>Son bülten</h2>${badge(c.status)}</div><div class="panel-body"><p>${esc(c.name)} · ${c.sent} gönderim · %${Math.round(c.open/c.sent*100)} açılma · %${Math.round(c.click/c.sent*100)} tıklama</p><div class="form-actions" style="justify-content:start">${btn('Kasım bültenini taslakla','newsletter-draft','primary','spark')}</div></div></div></section>`}
function mkForms(){return tbl(['FORM','UTM','LEAD','DÖNÜŞÜM',''],state.leadForms.map(f=>`<tr><td>${esc(f.name)}</td><td class="mono">${esc(f.utm)}</td><td>${f.leads}</td><td>${esc(f.conv)}</td><td>${btn('Linki kopyala','copy','sm','copy',`data-id="https://jobsstudio.co/f/${f.id}?${f.utm}"`)}</td></tr>`).join(''),'Lead yakalama formları')}
function mkFunnel(){const sent=state.campaigns.reduce((s,c)=>s+c.sent,0);const leads=state.leadForms.reduce((s,f)=>s+f.leads,0);const quotes=state.quotes.length;const won=state.leads.filter(l=>l.stage==='Kazanıldı').length;const spend=42000;return `<section class="metrics">${metric('Kampanya erişimi',sent,'gönderilen e-posta','mail')}${metric('Lead',leads,'form + UTM','crm')}${metric('Teklif',quotes,`%${Math.round(quotes/leads*100)} lead→teklif`,'present')}${metric('CAC',money(spend/Math.max(1,won)),`${money(spend)} harcama / ${won} kazanım`,'wallet')}</section><section class="panel"><div class="panel-header"><h2>Huni · kampanya → lead → teklif → kazanım</h2>${badge('Veri güveni: ORTA','warn')}</div><div class="panel-body">${svgBars([['Erişim',sent],['Lead',leads],['Teklif',quotes],['Kazanım',won]],{label:'Satış hunisi'})}<p class="small muted">Atıf: son tıklama · UTM parametreleri CRM lead kaydına yazılır.</p></div></section>`}

/* ---------- JS Events ---------- */
function events(){const parts={liste:evList,ros:evRos,tedarikci:evVendors,saha:evField,katilimci:evAttendees,butce:evBudget,ekipman:evEquipment};return head('ÜRETİM & MEDYA · JS EVENTS','Sahada her dakika planlı.','Edit Culture & Events komuta paneli: run-of-show dakika planı, tedarikçi teklif karşılaştırma, saha kontrol listesi (mobil), katılımcı/LCV, bütçe vs gerçekleşen, ekipman.',btn('Yeni etkinlik','event-new','primary','plus'))+`<div class="toolbar">${subnav()}</div>${sub!=='liste'?`<div class="toolbar"><label class="form-field" style="min-width:260px">Etkinlik<select data-ui-sel="event">${state.eventsList.map(e=>option(e.id,e.name,curEvent().id)).join('')}</select></label>${badge(curEvent().status)}<span class="muted small">${date(curEvent().date)} · ${esc(curEvent().venue)}</span></div>`:''}${(parts[sub]||evList)()}`}
const curEvent=()=>state.eventsList.find(e=>e.id===ui.event)||state.eventsList[0];
function evList(){return `<div class="project-grid">${state.eventsList.map(e=>`<article class="panel project-card"><div class="card-top"><div class="project-symbol">${esc(client(e.client)[0])}</div>${badge(e.status)}</div><h2>${esc(e.name)}</h2><p>${esc(client(e.client))} · ${esc(e.org)} · ${date(e.date)} · ${esc(e.venue)}</p><div class="progress"><span style="width:${Math.round(e.checklist.filter(c=>c[1]).length/Math.max(1,e.checklist.length)*100)}%"></span></div><div class="card-bottom"><span>${e.attendees.confirmed} / ${e.attendees.invited} LCV</span><span>${money(e.budget.actual)} / ${money(e.budget.planned)}</span></div><div class="actions" style="margin-top:10px">${btn('Run-of-show','ev-open','sm','events',`data-id="${e.id}" data-tab="ros"`)}${btn('Saha listesi','ev-open','sm','check',`data-id="${e.id}" data-tab="saha"`)}</div></article>`).join('')}</div>`}
function evRos(){const e=curEvent();const i=state.eventsList.indexOf(e);return `<section class="panel"><div class="panel-header"><h2>Run-of-show · ${esc(e.name)}</h2>${btn('Satır ekle','ros-add','sm','plus')}</div><div class="table-wrap"><table class="ros"><thead><tr><th>SAAT</th><th>AKIŞ</th><th>SORUMLU</th><th>DURUM</th></tr></thead><tbody>${e.ros.map((r,k)=>`<tr class="${r[3]?'done':''}"><td><input data-bind="eventsList.${i}.ros.${k}.0" value="${esc(r[0])}" aria-label="Saat" style="width:70px"></td><td><input data-bind="eventsList.${i}.ros.${k}.1" value="${esc(r[1])}" aria-label="Akış"></td><td>${esc(person(r[2]))}</td><td><button class="button sm" data-action="ros-toggle" data-id="${k}">${r[3]?'Tamamlandı ✓':'İşaretle'}</button></td></tr>`).join('')}</tbody></table></div></section>`}
function evVendors(){const e=curEvent();return `<div class="project-grid">${e.vendors.map((v,k)=>`<article class="panel contract-card"><div class="card-top"><h2>${esc(v.name)}</h2>${v.chosen?badge(`Seçildi: ${v.chosen}`,'success'):badge('Karar bekliyor')}</div><table class="vel-table"><thead><tr><th>TEDARİKÇİ</th><th>TEKLİF</th><th></th></tr></thead><tbody>${v.quotes.map(([n,p])=>`<tr class="${v.chosen===n?'chosen':''}"><td>${esc(n)}</td><td>${money(p)}</td><td>${v.chosen===n?badge('Seçili','success'):`<button class="button sm" data-action="vendor-choose" data-id="${k}" data-name="${esc(n)}">Seç</button>`}</td></tr>`).join('')}</tbody></table><p class="small muted" style="margin-top:8px">En düşük: ${money(Math.min(...v.quotes.map(q=>q[1])))} · fark ${money(Math.max(...v.quotes.map(q=>q[1]))-Math.min(...v.quotes.map(q=>q[1])))}</p></article>`).join('')}</div>`}
function evField(){const e=curEvent();const doneN=e.checklist.filter(c=>c[1]).length;return `<section class="panel field-list"><div class="panel-header"><h2>Saha kontrol listesi</h2>${badge(`${doneN}/${e.checklist.length}`,doneN===e.checklist.length?'success':'warn')}</div><div class="panel-body"><p class="small muted">Mobil kullanım için büyük dokunma alanları; çevrimdışı işaretler bağlantı gelince senkronlanır (demo).</p>${e.checklist.map((c,k)=>`<button class="field-item ${c[1]?'done':''}" data-action="field-toggle" data-id="${k}" aria-pressed="${c[1]}"><span class="check ${c[1]?'done':''}">${c[1]?ic('check'):''}</span><span>${esc(c[0])}</span></button>`).join('')}<form id="field-add-form" class="form-grid" style="margin-top:12px"><label class="form-field full">Yeni madde<input name="item" required maxlength="80"></label><div class="form-actions" style="grid-column:1/-1;justify-content:start"><button class="button sm" type="submit">Ekle</button></div></form></div></section>`}
function evAttendees(){const e=curEvent();const a=e.attendees;const pending=a.invited-a.confirmed-a.declined;return `<section class="metrics">${metric('Davetli',a.invited,'LCV formu gönderildi','mail')}${metric('Katılacak',a.confirmed,`%${Math.round(a.confirmed/Math.max(1,a.invited)*100)}`,'check')}${metric('Katılmayacak',a.declined,'','close')}${metric('Yanıt yok',Math.max(0,pending),'hatırlatma gönder','clock')}</section><div class="form-actions" style="justify-content:start">${btn('LCV hatırlatması gönder','lcv-remind','primary','mail')}${btn('Katılımcı listesi CSV','lcv-csv','','download')}${btn('QR yaka kartı üret','lcv-badge','','files')}</div>`}
function evBudget(){const e=curEvent();const pct=Math.round(e.budget.actual/e.budget.planned*100);const lines=[['Mekân',e.vendors.find(v=>v.name==='Mekân')?.quotes[0]?.[1]||60000,0],['Sahne & teknik',86000,0],['Catering',148000,0],['İçerik & prodüksiyon',26000,24000],['Baskı & yaka',12000,0],['Diğer',8000,4000]];return `<section class="metrics">${metric('Planlanan',money(e.budget.planned),'','wallet')}${metric('Gerçekleşen',money(e.budget.actual),`%${pct}`,'finance')}${metric('Taahhüt',money(e.vendors.filter(v=>v.chosen).reduce((s,v)=>s+(v.quotes.find(q=>q[0]===v.chosen)?.[1]||0),0)),'seçili tedarikçiler','approvals')}${metric('Kalan',money(e.budget.planned-e.budget.actual),'','clock')}</section>${tbl(['KALEM','PLAN','GERÇEKLEŞEN','FARK'],lines.map(([n,p,a])=>`<tr><td>${n}</td><td>${money(p)}</td><td>${money(a)}</td><td class="${a>p?'danger-text':''}">${money(p-a)}</td></tr>`).join(''),'Bütçe')}`}
function evEquipment(){const e=curEvent();return `<section class="panel"><div class="panel-header"><h2>Etkinlik ekipmanı</h2>${btn('Ekle','ev-eq-add','sm','plus')}</div><div class="panel-body">${e.equipment.map((x,k)=>`<div class="session-row"><div>${esc(x)}<small>${state.equipment.find(q=>q.name===x)?badge(state.equipment.find(q=>q.name===x).status,'neutral'):badge('Kiralık','neutral')}</small></div><button class="icon-button" data-action="ev-eq-remove" data-id="${k}" aria-label="${esc(x)} çıkar">${ic('trash')}</button></div>`).join('')||'<p class="empty">Ekipman eklenmedi.</p>'}</div></section>`}

Object.assign(views,{studio,social,media,review,transfer,present,marketing,events});
const asset=id=>state.assets.find(a=>a.id===id);
Object.assign(actions,{
'studio-brief-new'(){location.hash='studio/brief'},
'studio-generate'(){state.runs.unshift({id:'r'+Date.now(),agent:'Copy rol ikizi',trigger:'studio:concept',model:state.settings.ai.model,tokens:6100,cost:0.08,status:'Başarılı',at:now()});const c=state.concepts[0];c.text='Alternatif B — “Küçük adım, büyük ritim.”\n\nPost 1/12 — Her sabah aynı saat. Bir Wellana, bir plan. Günün ritmini sen kur.\n\nPost 2/12 — Sonbahar yorgunluğu gerçek. Rutin de öyle…\n\n(Copy rol ikizi · taslak · ECD ön-kontrolü gerekli)';c.version='v3';c.versions.push({v:'v3',at:now(),note:'Alternatif B (Copy rol ikizi)'});c.ecd={tone:true,banned:true,visual:true,claim:true,length:true};location.hash='studio/taslak';done('Alternatif konsept üretildi (v3).','AI konsept taslağı üretildi: v3')},
'concept-version'(){const c=state.concepts[0];const n='v'+(c.versions.length+1);c.version=n;c.versions.push({v:n,at:now(),note:`${account().name} düzenlemesi`});done(`${n} kaydedildi.`,`Konsept sürümü kaydedildi: ${n}`)},
'concept-restore'(b){const c=state.concepts.find(x=>x.id===b.dataset.id);if(!c)return;c.version=b.dataset.v;done(`${b.dataset.v} geri alındı.`,`Konsept sürümü geri alındı: ${b.dataset.v}`)},
'concept-approve'(){const c=state.concepts[0];c.status='ECD onaylı';requestApproval({name:`${c.title} · metin seti`,project:'p1',kind:'İçerik',desc:'ECD ön-kontrolü 5/5; müşteri onayına hazır.'});done('ECD onayı verildi; Onay Merkezi’ne düştü.',`ECD onayı: ${c.title}`)},
'concept-to-social'(){const c=state.concepts[0];[16,23].forEach((d,i)=>state.social.push({id:uid('s'),client:c.client,month:'2026-10',day:d,channel:'Instagram',text:`Ritmin kalsın · taslak ${i+1}`,stage:'Metin',visual:'görsel'}));ui.socialBrand=c.client;location.hash='social/takvim';done('2 içerik JS Social takvimine eklendi.',`Konsept JS Social’a aktarıldı: ${c.title}`)},
'social-plan'(){const id=ui.socialBrand||'c_badem';const ct=state.contracts.find(c=>c.client===id);const n=ct?ct.quota.social:8;const added=[];for(let i=0;i<n;i++){const day=3+i*3;if(day>30)break;if(!state.social.some(s=>s.client===id&&s.month==='2026-11'&&s.day===day)){state.social.push({id:uid('s'),client:id,month:'2026-11',day,channel:i%4===3?'Reels':'Instagram',text:`Kasım plan · ${['tema','ürün','topluluk','Reels'][i%4]} ${i+1}`,stage:'Fikir',visual:i%4===3?'video':'görsel'});added.push(day)}}state.runs.unshift({id:'r'+Date.now(),agent:'SM rol ikizi',trigger:`social:plan:${id}`,model:state.settings.ai.model,tokens:5400,cost:0.07,status:'Başarılı',at:now()});done(`Kasım planı üretildi: ${added.length} içerik (kota ${n}).`,`SM rol ikizi aylık plan üretti: ${client(id)} Kasım · ${added.length} içerik`)},
'social-new'(){const id=ui.socialBrand||'c_badem';state.social.push({id:uid('s'),client:id,month:'2026-10',day:27,channel:'Instagram',text:'Yeni içerik',stage:'Fikir',visual:'görsel'});done('İçerik eklendi; karta tıklayıp düzenle.',`Sosyal içerik eklendi: ${client(id)}`)},
'social-open'(b){socialDetail(b.dataset.id)},
'social-move'(b){const s=state.social.find(x=>x.id===b.dataset.id);if(!s)return;s.stage=b.dataset.to;if(s.stage==='Müşteri onayı')requestApproval({name:`${client(s.client)} · ${s.text}`,project:state.projects.find(p=>p.client===s.client)?.id||'',kind:'Müşteri kararı',desc:`${s.channel} · ${s.day} Ekim · müşteri portalında onay bekliyor`});done(`→ ${s.stage}`,`Sosyal içerik aşaması: ${s.text} → ${s.stage}`)},
'social-delete'(b){state.social=state.social.filter(x=>x.id!==b.dataset.id);closeDialog();done('İçerik silindi.','Sosyal içerik silindi.')},
'social-bulk'(b){const id=b.dataset.id;const items=state.social.filter(s=>s.client===id&&s.month==='2026-10'&&s.stage==='İç onay');items.forEach(s=>s.stage='Müşteri onayı');if(items.length)requestApproval({name:`${client(id)} Ekim takvimi · ${items.length} içerik toplu onay`,project:state.projects.find(p=>p.client===id)?.id||'',kind:'Müşteri kararı',desc:'Portal → Onaylar → sosyal takvim toplu onay'});done(items.length?`${items.length} içerik müşteri onayına gönderildi.`:'İç onayda bekleyen içerik yok.',`Toplu müşteri onayı: ${client(id)} · ${items.length} içerik`)},
'file-preview'(b){const a=asset(b.dataset.id);const name=a?.name||b.dataset.id;openDialog(esc(name),`<div class="dialog-body"><div class="cover alt" style="height:180px;border-radius:12px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:22px">${a?.type==='Video'?ic('play'):''} Önizleme · demo</div><p style="margin-top:16px">${a?.provider==='Vimeo'?'Vimeo oynatıcı referansı (video ID '+esc(a.vimeoId)+').':'Üretimde MinIO ön-imzalı URL (15 dk) ile açılır; prototipte dosya içeriği yoktur.'} Erişim JS Core yetki modeline bağlıdır; bu önizleme audit’e yazıldı.</p><div class="form-actions">${btn('Kapat','close','','close')}</div></div>`);log(`Dosya önizlendi: ${name}`)},
'file-share'(b){const a=asset(b.dataset.id);const name=a?.name||b.dataset.id;openDialog('Paylaşım linki oluştur',`<form class="dialog-body" id="share-form" data-file="${esc(name)}"><p>${esc(name)} · JS Transfer linki. Kalıcı storage adresi paylaşılmaz; yetki kontrolünden sonra kısa ömürlü imzalı URL üretilir.</p><div class="form-grid"><label class="form-field">Süre<select name="days"><option value="3">3 gün</option><option value="7" selected>7 gün</option><option value="30">30 gün</option></select></label><label class="form-field">İndirme limiti<input type="number" name="limit" min="1" value="5"></label><label class="form-field full"><input type="checkbox" name="password" checked> Şifre iste</label></div><div class="form-actions">${btn('Vazgeç','close','','close')}<button class="button primary" type="submit">Link üret ${ic('link')}</button></div></form>`)},
'share-new'(){actions['file-share']({dataset:{id:state.assets[0].id}})},
'share-revoke'(b){const l=state.shareLinks.find(x=>x.id===b.dataset.id);if(!l)return;l.revoked=true;emit('share.revoked',`share:${l.id}`);done('Link iptal edildi; erişim anında kapandı.',`Paylaşım linki iptal edildi: ${l.file}`)},
'share-extend'(b){const l=state.shareLinks.find(x=>x.id===b.dataset.id);if(!l)return;l.expires='2026-10-28';done('Süre 28 Ekim’e uzatıldı.',`Paylaşım süresi uzatıldı: ${l.file}`)},
'upload-start'(){const name=$('#up-name')?.value||'dosya.mp4';const to=$('#up-to')?.value||'MinIO';ui.upload={name,to,pct:0,stage:'Parçalı yükleme başladı'};render();clearInterval(ui.upTimer);ui.upTimer=setInterval(()=>{const u=ui.upload;if(!u)return clearInterval(ui.upTimer);u.pct=Math.min(100,u.pct+Math.ceil(Math.random()*18));u.stage=u.pct<70?`Parça ${Math.ceil(u.pct/10)}/10 yükleniyor`:u.pct<100?'Checksum & virüs taraması':'Asset kaydı oluşturuldu';const bar=$('#up-bar'),pct=$('#up-pct'),st=$('#up-stage');if(bar)bar.style.width=u.pct+'%';if(pct)pct.textContent='%'+u.pct;if(st)st.textContent=u.stage;if(u.pct>=100){clearInterval(ui.upTimer);state.uploads.unshift({id:uid('u'),name:u.name,size:'1,1 GB',to:u.to,status:'Tamamlandı',at:now(),checksum:'sha256:'+randomToken().slice(4,8)+'…'+randomToken().slice(-4)});state.assets.unshift({id:uid('f'),name:u.name,type:'Video',provider:'MinIO',key:'jobs-media/'+u.name,client:'c_anova',project:'p3',size:'1,1 GB',folder:'Yüklemeler',created:TODAY,retention:'2029-10-14',status:'Taslak'});emit('file.uploaded',`file:${u.name}`);ui.upload=null;addNotification(`Dosya yüklendi: ${u.name} (${u.to})`,'media');done('Yükleme tamamlandı; asset kaydı oluşturuldu.',`Dosya yüklendi: ${u.name} → ${u.to}`)}},350);log(`Yükleme başlatıldı: ${name}`)},
'review-open'(b){const r=state.reviews.find(x=>x.asset===b.dataset.id);if(r)ui.review=r.id;location.hash='review/inceleme';if(route==='review')render()},
'review-version'(){const r=state.reviews.find(x=>x.id===ui.review)||state.reviews[0];const n='v'+(r.versions.length+1);r.versions.push({v:n,at:now(),duration:r.versions.at(-1).duration,comments:[]});r.current=n;r.rounds.used++;r.status='İncelemede';ui.rv=n;emit('review.version.created',`review:${r.id}`);done(`${n} yüklendi · revize turu ${r.rounds.used}/${r.rounds.included}${r.rounds.used>r.rounds.included?' — kapsam dışı, ek teklif gerekir':''}.`,`İnceleme sürümü eklendi: ${r.name} ${n}`)},
'rv-filter'(b){ui.rvFilter=b.dataset.id;render()},
'rv-resolve'(b){const r=state.reviews.find(x=>x.id===b.dataset.id);const c=r?.versions.find(v=>v.v===b.dataset.v)?.comments.find(x=>x.id===b.dataset.c);if(!c)return;c.resolved=true;done('Yorum çözüldü olarak işaretlendi.',`Review yorumu çözüldü: ${r.name} ${b.dataset.v} ${c.tc}`)},
'rv-vis'(b){const r=state.reviews.find(x=>x.id===b.dataset.id);const c=r?.versions.find(v=>v.v===b.dataset.v)?.comments.find(x=>x.id===b.dataset.c);if(!c)return;c.internal=!c.internal;done(c.internal?'Yorum dahili yapıldı.':'Yorum müşteriye açıldı.',`Review yorumu görünürlük: ${c.tc} → ${c.internal?'dahili':'müşteri'}`)},
'rv-approve'(b){const r=state.reviews.find(x=>x.id===b.dataset.id);if(!r)return;r.status='Onaylandı';const a=asset(r.asset);if(a)a.status='Onaylı';emit('review.approved',`review:${r.id}`);const ap=state.approvals.find(x=>x.review===r.id&&x.status==='Bekliyor');if(ap){ap.status='Onaylandı';ap.feedback='JS Review’dan onaylandı'}addNotification(`${r.name} ${r.current} onaylandı → JS Transfer linki hazır.`,'transfer/linkler');done(`${r.current} onaylandı. Teslim için Transfer linki oluşturabilirsin.`,`Video onayı: ${r.name} ${r.current} (${isClient()?'müşteri':'iç'})`)},
'rv-revise'(b){const r=state.reviews.find(x=>x.id===b.dataset.id);if(!r)return;r.status='Revizyon';r.rounds.used++;const over=r.rounds.used>r.rounds.included;state.tasks.unshift({id:uid('t'),name:`${r.name} · revizyon ${r.current}→v${r.versions.length+1}`,project:r.project,owner:'HO',done:false,date:date('2026-10-17'),due:'2026-10-17',priority:'Yüksek',stage:'Üretim',labels:['video','revizyon'],type:'Video kurgu',sla:72,logged:0,comments:[],client_visible:true,source:`JS Review ${r.id}`});if(over)requestApproval({name:`${r.name} · ${r.rounds.used}. revize turu (kapsam dışı)`,project:r.project,kind:'Kapsam dışı',amount:8500,desc:`Sözleşmede ${r.rounds.included} tur dahil; ek tur teklif gerektirir.`});done(over?`Revizyon görevi açıldı · ${r.rounds.used}. tur kapsam dışı → Onay Merkezi.`:`Revizyon görevi açıldı · tur ${r.rounds.used}/${r.rounds.included}.`,`Revizyon istendi: ${r.name} ${r.current} (tur ${r.rounds.used})`)},
'rv-link'(b){const r=state.reviews.find(x=>x.id===b.dataset.id);if(!r)return;r.externalLink=`https://review.jobsstudio.co/r/${Math.random().toString(36).slice(2,8)}`;emit('review.link.created',`review:${r.id}`);done('Dış inceleyici linki oluşturuldu (7 gün).',`Dış inceleyici linki: ${r.name}`)},
'rv-link-revoke'(b){const r=state.reviews.find(x=>x.id===b.dataset.id);if(!r)return;r.externalLink='';done('Link iptal edildi.',`Dış inceleyici linki iptal: ${r.name}`)},
'vimeo-run'(){const v=state.vimeoImport;v.imported+=v.pending;v.pending=0;v.lastRun=now();done('Bekleyen Vimeo kayıtları içe aktarıldı.','Vimeo içe aktarım çalıştırıldı.')},
'vimeo-retry'(){const v=state.vimeoImport;v.imported+=v.errors;v.errors=0;done('Hatalı kayıtlar yeniden denendi: başarılı.','Vimeo hatalı kayıtlar yeniden denendi.')},
'retention-extend'(b){const a=asset(b.dataset.id);if(!a)return;a.retention='2032-01-01';done('Saklama süresi uzatıldı (2032).',`Saklama uzatıldı: ${a.name}`)},
'doc-new'(b){const kind=b.dataset.kind||'Teklif';state.documents.unshift({id:uid('d'),type:kind,name:`Yeni ${kind.toLocaleLowerCase('tr')} · ${now()}`,client:'c_anova',status:'Taslak',updated:now(),pages:kind==='Rapor'?8:kind==='Sunum'?16:12});location.hash='present/'+{Teklif:'teklif',Sunum:'sunum',Rapor:'rapor'}[kind];done(`${kind} taslağı oluşturuldu.`,`JS Present belge oluşturuldu: ${kind}`)},
'doc-generate'(b){const d=state.documents.find(x=>x.id===b.dataset.id);if(!d)return;d.updated=now();state.runs.unshift({id:'r'+Date.now(),agent:'Present AI',trigger:`doc:${d.id}`,model:state.settings.ai.model,tokens:7700,cost:0.1,status:'Başarılı',at:now()});done(`${d.type} taslağı şablondan üretildi (${d.pages} sayfa).`,`Belge taslağı üretildi: ${d.name}`)},
'doc-send'(b){const d=state.documents.find(x=>x.id===b.dataset.id);if(!d)return;d.status='Gönderildi';done('Belge müşteriye gönderildi (simülasyon).',`Belge gönderildi: ${d.name}`)},
'present-pdf'(b){const q=state.quotes.find(x=>x.id===b.dataset.id);const txt=q?`JOBS STUDIO · TEKLİF ${q.id}\n${q.name}\n\n${q.items.map(([d,n,p])=>`${d} × ${n} — ${money(n*p)}`).join('\n')}\n\nToplam: ${money(q.items.reduce((s,[,n,p])=>s+n*p,0))}\nİkiz saat tahmini: ${q.hours}\n\nDemo belge; PDF üretimi üretim fazında.`:`JOBS STUDIO · BELGE\n${b.dataset.id}\n\nDemo belge taslağı.`;download(`${b.dataset.id}-taslak.txt`,txt);toast('PDF taslağı (metin) indiriliyor.');log(`PDF taslağı üretildi: ${b.dataset.id}`)},
'campaign-new'(){openDialog('Yeni mailing kampanyası',`<form class="dialog-body" id="campaign-form"><div class="form-grid"><label class="form-field full">Ad<input name="name" required></label><label class="form-field">Segment<select name="segment">${state.segments.map(s=>option(s.id,`${s.name} (${s.kvkk} izinli)`)).join('')}</select></label><label class="form-field">Şablon<select name="template"><option>Bülten</option><option>Ürün tanıtımı</option><option>Etkinlik daveti</option></select></label><label class="form-field">Konu A<input name="subjectA" required></label><label class="form-field">Konu B (A/B)<input name="subjectB"></label></div><div class="form-actions"><button class="button primary" type="submit">Taslak oluştur ${ic('plus')}</button></div></form>`)},
'campaign-test'(b){done('Test e-postası gönderildi: '+account().email,`Kampanya testi: ${state.campaigns.find(c=>c.id===b.dataset.id)?.name}`,false)},
'campaign-schedule'(b){const c=state.campaigns.find(x=>x.id===b.dataset.id);if(!c)return;c.status='Zamanlandı';c.at='21.10 10:00';done('Kampanya zamanlandı: 21.10 10:00.',`Kampanya zamanlandı: ${c.name}`)},
'campaign-send'(b){const c=state.campaigns.find(x=>x.id===b.dataset.id);if(!c)return;const seg=state.segments.find(s=>s.id===c.segment);c.status='Gönderildi';c.sent=seg.kvkk;c.open=Math.round(seg.kvkk*.31);c.click=Math.round(seg.kvkk*.04);c.winner=c.subjectB?'B':'A';c.at=now();emit('campaign.sent',`campaign:${c.id}`);done(`Gönderildi: ${c.sent} kişi (yalnızca KVKK izinli).`,`Kampanya gönderildi: ${c.name} → ${c.sent}`)},
'newsletter-draft'(){state.campaigns.unshift({id:uid('cm'),name:'Kasım bülteni · “Ajans notları”',segment:'sg2',status:'Taslak',sent:0,open:0,click:0,subjectA:'Kasım: yıl sonu hazırlığı',subjectB:'3 etkinlik, 1 lansman',winner:'',at:'—'});location.hash='marketing/kampanya';done('Kasım bülteni taslağı oluşturuldu.','Bülten taslağı oluşturuldu: Kasım')},
'event-new'(){openDialog('Yeni etkinlik',`<form class="dialog-body" id="event-form"><div class="form-grid"><label class="form-field full">Ad<input name="name" required></label><label class="form-field">Marka<select name="client">${state.clients.map(c=>option(c.id,c.name)).join('')}</select></label><label class="form-field">Tarih<input type="date" name="date" value="2026-12-10"></label><label class="form-field">Mekân<input name="venue" value="Ankara"></label><label class="form-field">Bütçe (₺)<input type="number" name="budget" value="150000"></label></div><div class="form-actions"><button class="button primary" type="submit">Oluştur ${ic('plus')}</button></div></form>`)},
'ev-open'(b){ui.event=b.dataset.id;location.hash='events/'+b.dataset.tab},
'ros-add'(){curEvent().ros.push(['--:--','Yeni akış satırı',account().person,false]);done('Satır eklendi.',`Run-of-show satırı eklendi: ${curEvent().name}`)},
'ros-toggle'(b){const r=curEvent().ros[Number(b.dataset.id)];r[3]=!r[3];done(null,`Run-of-show: ${r[1]} ${r[3]?'tamamlandı':'yeniden açıldı'}`)},
'vendor-choose'(b){const v=curEvent().vendors[Number(b.dataset.id)];v.chosen=b.dataset.name;const price=v.quotes.find(q=>q[0]===v.chosen)?.[1]||0;if(price>state.settings.structure.level0Max)requestApproval({name:`${curEvent().name} · ${v.name}: ${v.chosen}`,project:state.projects.find(p=>p.client===curEvent().client)?.id||'',kind:'Bütçe',amount:price,desc:`Tedarikçi seçimi · ${approvalLevel(price)}`});done(`${v.chosen} seçildi${price>state.settings.structure.level0Max?' · onaya gönderildi':''}.`,`Tedarikçi seçildi: ${v.name} → ${v.chosen} (${money(price)})`)},
'field-toggle'(b){const c=curEvent().checklist[Number(b.dataset.id)];c[1]=!c[1];done(null,`Saha kontrol: ${c[0]} ${c[1]?'✓':'geri alındı'}`)},
'lcv-remind'(){const e=curEvent();e.attendees.confirmed+=12;e.attendees.declined+=3;done('LCV hatırlatması gönderildi; 15 yeni yanıt (simülasyon).',`LCV hatırlatması: ${e.name}`)},
'lcv-csv'(){csv('katilimcilar.csv',[['Ad','Şirket','LCV'],['Örnek Katılımcı 1',client(curEvent().client),'Katılacak'],['Örnek Katılımcı 2',client(curEvent().client),'Yanıt yok']]);toast('Katılımcı listesi indiriliyor (örnek).')},
'lcv-badge'(){done('QR yaka kartları üretildi (PDF, simülasyon).',`Yaka kartı üretimi: ${curEvent().name}`,false)},
'ev-eq-add'(){curEvent().equipment.push('Yeni ekipman (kiralık)');done('Ekipman eklendi.','Etkinlik ekipmanı eklendi.')},
'ev-eq-remove'(b){curEvent().equipment.splice(Number(b.dataset.id),1);done('Çıkarıldı.','Etkinlik ekipmanı çıkarıldı.')}
});
Object.assign(forms,{
'brief-form'(get){state.briefs.unshift({id:uid('br'),client:get('client'),title:get('title'),goal:get('goal'),audience:get('audience'),outputs:get('outputs'),success:get('success'),limits:get('limits'),status:'Taslak',at:new Date().toLocaleDateString('tr-TR')});done('Brief kaydedildi (5/5 unsur).',`Brief kaydedildi: ${get('title')}`)},
'review-comment-form'(get,data,f){const r=state.reviews.find(x=>x.id===f.dataset.id);const v=r?.versions.find(x=>x.v===f.dataset.v);if(!v)return;v.comments.push({id:uid('c'),tc:get('tc'),who:account().name,text:get('text'),internal:get('vis')==='internal',resolved:false});emit('review.comment.added',`review:${r.id}`);done('Yorum eklendi.',`Review yorumu: ${r.name} ${v.v} ${get('tc')}`)},
'share-form'(get,data,f){const d=new Date(TODAY+'T12:00:00');d.setDate(d.getDate()+Number(get('days')));const l={id:uid('sl'),file:f.dataset.file,url:`https://transfer.jobsstudio.co/s/${Math.random().toString(36).slice(2,8)}`,expires:d.toISOString().slice(0,10),password:data.get('password')==='on',limit:Number(get('limit')),downloads:0,revoked:false,created:now(),by:account().person};state.shareLinks.unshift(l);emit('share.created',`share:${l.id}`);closeDialog();log(`Paylaşım linki oluşturuldu: ${l.file} (${get('days')} gün, limit ${l.limit}${l.password?', şifreli':''})`);openDialog('Paylaşım linki hazır',`<div class="dialog-body"><p>${esc(l.file)} · ${date(l.expires)} tarihine kadar · ${l.limit} indirme · ${l.password?'şifre: <code class="mono">JS-'+Math.random().toString(36).slice(2,6).toUpperCase()+'</code>':'şifresiz'}</p><div class="token-box">${l.url}</div><div class="form-actions">${btn('Kopyala','copy','','copy',`data-id="${l.url}"`)}${btn('Linkleri gör','goto','primary','transfer','data-id="transfer/linkler"')}</div></div>`)},
'file-request-form'(get){state.fileRequests.unshift({id:uid('fr'),to:get('to'),what:get('what'),url:`https://transfer.jobsstudio.co/req/${Math.random().toString(36).slice(2,6)}`,expires:get('expires'),received:0,created:now()});done('Dosya isteme linki oluşturuldu ve e-posta taslağı hazırlandı.',`Dosya isteği: ${get('to')} · ${get('what')}`)},
'campaign-form'(get){state.campaigns.unshift({id:uid('cm'),name:get('name'),segment:get('segment'),status:'Taslak',sent:0,open:0,click:0,subjectA:get('subjectA'),subjectB:get('subjectB'),winner:'',at:'—'});closeDialog();done('Kampanya taslağı oluşturuldu.',`Kampanya oluşturuldu: ${get('name')}`)},
'event-form'(get){state.eventsList.push({id:uid('ev'),name:get('name'),client:get('client'),org:'Edit Culture & Events',date:get('date'),venue:get('venue'),status:'Planlama',attendees:{invited:0,confirmed:0,declined:0},budget:{planned:Number(get('budget')),actual:0},ros:[['--:--','Açılış',account().person,false]],vendors:[],checklist:[['Mekân seçimi',false]],equipment:[]});closeDialog();done('Etkinlik oluşturuldu.',`Etkinlik oluşturuldu: ${get('name')}`)},
'field-add-form'(get){curEvent().checklist.push([get('item'),false]);done('Madde eklendi.',`Saha kontrol maddesi: ${get('item')}`)}
});
